// 21 · VALVE ENGINEER — route liquid through a network to exact target volumes.
// Rules (deterministic, shown on screen): every open valve passes its rate (u²/s) downhill while its source
// holds liquid; a container filled past capacity spills the excess (lost). Nothing is created or destroyed.
// Each puzzle is generated by simulating a hidden valid plan, so its targets are always reachable.
// Space pauses (plan while paused); Done closes every valve and measures.
import { Controls } from '../core/controls';
import { clamp, font, line, pal, tag, text } from '../core/draw';
import { gameKey, listen, primary } from '../core/input';
import { glassWall, liquidBody, liquidSurface, softShadow } from '../core/materials';
import { rng } from '../core/rng';
import type { GameFactory, Level } from '../core/types';

export const VDT = 1 / 60;
const KEYS = ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k'];

export interface Node {
  name: string;
  x: number;
  y: number; // field units, centre of the container
  w: number;
  h: number;
  cap: number; // = w·h
  V0: number;
  goal: number | null; // target volume (targets only)
}
export interface Pipe {
  from: number;
  to: number;
  rate: number; // u² per second
}
export interface ValvePuzzle {
  nodes: Node[];
  pipes: Pipe[];
  /** Maximum valve operations (open or close), or Infinity. */
  ops: number;
}

/** One fixed step: every open valve moves min(rate·dt, what its source holds); overfull containers spill. */
export function valveStep(nodes: Node[], pipes: Pipe[], V: number[], open: boolean[], dt: number, infinite = false) {
  const next = V.slice();
  let spilled = 0;
  pipes.forEach((p, i) => {
    if (!open[i]) return;
    const q = infinite && nodes[p.from].goal == null && !pipes.some((pp) => pp.to === p.from) ? p.rate * dt : Math.min(p.rate * dt, next[p.from]);
    if (q <= 0) return;
    next[p.from] -= q;
    next[p.to] += q;
  });
  next.forEach((v, i) => {
    if (v > nodes[i].cap) {
      spilled += v - nodes[i].cap;
      next[i] = nodes[i].cap;
    }
    if (infinite && nodes[i].goal == null && !pipes.some((pp) => pp.to === i)) next[i] = nodes[i].V0;
  });
  return { V: next, spilled };
}

/** Run a plan: valve i open from t = 0 to t = close[i] (s). Returns final volumes and spill. */
export function runPlan(pz: ValvePuzzle, close: number[]) {
  let V = pz.nodes.map((n) => n.V0);
  let spilled = 0;
  const T = Math.max(0, ...close);
  for (let t = 0; t < T + VDT / 2; t += VDT) {
    const open = close.map((c) => t + 1e-9 < c);
    const r = valveStep(pz.nodes, pz.pipes, V, open, VDT);
    V = r.V;
    spilled += r.spilled;
  }
  return { V, spilled };
}

const box = (name: string, x: number, y: number, w: number, h: number, V0: number, goal: number | null = null): Node => ({ name, x, y, w, h, cap: w * h, V0, goal });

function template(level: Level, r: ReturnType<typeof rng>): ValvePuzzle {
  const rate = (lo: number, hi: number) => Math.round(r.range(lo, hi));
  if (level === 'easy') {
    return {
      nodes: [box('S', 0, -32, 30, 16, 400), box('T1', -26, 26, 18, 16, 0, 0), box('T2', 26, 26, 18, 16, 0, 0)],
      pipes: [
        { from: 0, to: 1, rate: rate(18, 28) },
        { from: 0, to: 2, rate: rate(18, 28) },
      ],
      ops: Infinity,
    };
  }
  if (level === 'medium') {
    return {
      nodes: [box('S1', -26, -34, 22, 14, 280), box('S2', 26, -34, 22, 14, 280), box('M', 0, -4, 20, 10, 0), box('T1', -32, 28, 16, 14, 0, 0), box('T2', 0, 28, 16, 14, 0, 0), box('T3', 32, 28, 16, 14, 0, 0)],
      pipes: [
        { from: 0, to: 2, rate: rate(16, 26) },
        { from: 1, to: 2, rate: rate(16, 26) },
        { from: 2, to: 3, rate: rate(14, 22) },
        { from: 2, to: 4, rate: rate(14, 22) },
        { from: 1, to: 5, rate: rate(10, 18) },
      ],
      ops: Infinity,
    };
  }
  return {
    nodes: [
      box('S1', -28, -36, 22, 12, 260),
      box('S2', 28, -36, 22, 12, 260),
      box('M1', -18, -8, 16, 9, 0),
      box('M2', 18, -8, 14, 8, 0),
      box('T1', -36, 28, 14, 14, 0, 0),
      box('T2', -12, 28, 14, 14, 0, 0),
      box('T3', 12, 28, 14, 14, 0, 0),
      box('T4', 36, 28, 14, 14, 0, 0),
    ],
    pipes: [
      { from: 0, to: 2, rate: rate(10, 24) },
      { from: 0, to: 3, rate: rate(8, 16) },
      { from: 1, to: 3, rate: rate(10, 24) },
      { from: 2, to: 4, rate: rate(8, 20) },
      { from: 2, to: 5, rate: rate(8, 20) },
      { from: 3, to: 6, rate: rate(8, 20) },
      { from: 3, to: 5, rate: rate(6, 12) },
      { from: 1, to: 7, rate: rate(8, 20) },
    ],
    ops: 14,
  };
}

/** A puzzle whose goals come from a hidden plan that works without spilling. */
export function makeValves(seed: number, level: Level): ValvePuzzle {
  const r = rng(seed);
  for (let tries = 0; tries < 400; tries++) {
    const pz = template(level, r);
    // Hidden plan. Easy/Medium: every valve open for a random time. Hard: a real route to each target
    // (S1→M1→T1; T2 via M1 or via M2; M2 fed from S1 or S2, then →T3; S2→T4), so the plan feeds every
    // target with at most six valves — twelve operations, inside the limit of fourteen.
    let close: number[];
    if (level === 'hard') {
      const used = new Set([0, 3, 5, 7, r.pick([1, 2]), r.pick([4, 6])]);
      close = pz.pipes.map((_, i) => (used.has(i) ? r.range(1, 4.5) : 0));
    } else close = pz.pipes.map(() => r.range(1.2, 5.5));
    const res = runPlan(pz, close);
    if (res.spilled > 0.01) continue;
    const goals = pz.nodes.map((n, i) => (n.goal == null ? null : Math.round(res.V[i])));
    if (goals.some((g, i) => pz.nodes[i].goal != null && (g == null || g < 20 || g > pz.nodes[i].cap - 10))) continue;
    const opsNeeded = close.filter((c) => c > 0).length * 2;
    if (pz.ops !== Infinity && opsNeeded > pz.ops - 2) continue;
    pz.nodes.forEach((n, i) => (n.goal = goals[i]));
    return pz;
  }
  const pz = template('easy', r);
  pz.nodes[1].goal = 60;
  pz.nodes[2].goal = 80;
  return pz;
}

/** Score: (Σ |volume − goal| over targets + spilled) ÷ Σ goals, as a percentage. */
export function valveScore(pz: ValvePuzzle, V: number[], spilled: number) {
  let err = 0;
  let total = 0;
  pz.nodes.forEach((n, i) => {
    if (n.goal == null) return;
    err += Math.abs(V[i] - n.goal);
    total += n.goal;
  });
  return { pct: ((err + spilled) / total) * 100, err, spilled, total };
}

const factory: GameFactory = (api) => {
  const { stage } = api;
  let pz: ValvePuzzle = makeValves(1, 'easy');
  let V: number[] = [];
  let open: boolean[] = [];
  let spilled = 0;
  let ops = 0;
  let simT = 0;
  let clock0 = 0;
  let pausedAt: number | null = null;
  let pausedTotal = 0;
  let phase: 'run' | 'done' = 'run';
  let finTimer = 0;
  let lastMsg = '';
  const sandbox = () => api.mode === 'sandbox';
  const controls = new Controls(stage, () => done());

  const layout = () => {
    const W = stage.w;
    const H = stage.h;
    const top = 70;
    const F = Math.max(170, Math.min(W - 32, H - top - 70, 640));
    return { k: F / 100, F, cx: W / 2, cy: top + F / 2, ctrlY: top + F + 4 };
  };

  const simTarget = (t: number) => ((pausedAt ?? t) - clock0 - pausedTotal) / 1000;
  function advance(t: number) {
    if (phase !== 'run') return;
    const target = simTarget(t);
    let n = 0;
    while (simT + VDT <= target && n++ < 3000) {
      const r = valveStep(pz.nodes, pz.pipes, V, open, VDT, sandbox());
      if (r.spilled > 0 && !lastMsg) lastMsg = 'Overflow! A container filled past its capacity — the excess is lost.';
      V = r.V;
      spilled += r.spilled;
      simT += VDT;
    }
  }

  function reset(seed: number) {
    clearTimeout(finTimer);
    pz = makeValves(seed, api.level);
    V = pz.nodes.map((n) => n.V0);
    open = pz.pipes.map(() => false);
    spilled = 0;
    ops = 0;
    simT = 0;
    clock0 = performance.now();
    pausedAt = null;
    pausedTotal = 0;
    phase = 'run';
    lastMsg = '';
    controls.set([]);
    controls.enabled = true;
    controls.touched = true;
    controls.lockLabel = sandbox() ? 'Reset' : 'Done';
    api.progress(sandbox() ? 'sandbox' : pz.ops === Infinity ? '' : `0 / ${pz.ops} ops`);
    api.prompt(
      sandbox() ? 'Sandbox: sources never run dry. Open valves, watch the flow, cause an overflow.' : 'Fill every target to its mark — exactly.',
      `Tap a valve (or its key) to open / close · Space pauses · ${sandbox() ? 'Reset with Enter' : 'Done when finished'}${pz.ops !== Infinity ? ` · at most ${pz.ops} valve operations` : ''}`,
    );
    stage.request();
  }

  function toggle(i: number, ts: number) {
    if (phase !== 'run' || i >= pz.pipes.length) return;
    if (!sandbox() && ops >= pz.ops) {
      api.sfx.over();
      api.prompt('No valve operations left.', 'Press Done to measure what you have');
      return;
    }
    advance(ts);
    open[i] = !open[i];
    ops++;
    api.sfx.tick();
    if (!sandbox() && pz.ops !== Infinity) api.progress(`${ops} / ${pz.ops} ops`);
    stage.request();
  }

  function togglePause(ts: number) {
    if (phase !== 'run') return;
    if (pausedAt == null) {
      advance(ts);
      pausedAt = ts;
      api.prompt('Paused — plan your next move.', 'Space resumes · valves you toggle now take effect on resume');
    } else {
      pausedTotal += ts - pausedAt;
      pausedAt = null;
      api.prompt('');
    }
    stage.request();
  }

  function done() {
    if (sandbox()) return reset(Math.floor(Math.random() * 0xffffffff));
    if (phase !== 'run') return;
    advance(performance.now());
    open = open.map(() => false);
    phase = 'done';
    const s = valveScore(pz, V, spilled);
    const disp = s.pct.toFixed(1);
    const rows: [string, string][] = pz.nodes
      .map((n, i) => (n.goal == null ? null : ([`${n.name} · goal ${n.goal}`, `${V[i].toFixed(1)} (${V[i] >= n.goal ? '+' : '−'}${Math.abs(V[i] - n.goal).toFixed(1)})`] as [string, string])))
      .filter((x): x is [string, string] => !!x);
    rows.push(['Spilled (overflow)', spilled.toFixed(1)]);
    rows.push(['Valve operations', pz.ops === Infinity ? String(ops) : `${ops} of ${pz.ops}`]);
    rows.push(['Time', `${simT.toFixed(1)} s of flow`]);
    rows.push(['Score', '(Σ |volume − goal| + spilled) ÷ Σ goals']);
    api.sfx.release();
    stage.request();
    finTimer = window.setTimeout(
      () =>
        api.finish({
          score: s.pct,
          value: disp,
          unit: '%',
          label: 'volume error (of the total goal)',
          headline: disp === '0.0' ? 'Every target exact, nothing spilled.' : `${s.err.toFixed(1)} u² off target${s.spilled > 0.05 ? ` and ${s.spilled.toFixed(1)} u² spilled` : ''} — ${disp}% of the ${s.total} u² you had to deliver.`,
          rows,
          perfect: disp === '0.0',
          near: s.pct < 1,
          share: [`VALVE ENGINEER · ${api.level} — route liquid to exact volumes`, `${disp}% off`],
        }),
      api.motion() ? 500 : 0,
    );
  }

  const valvePos = (p: Pipe) => {
    const a = pz.nodes[p.from];
    const b = pz.nodes[p.to];
    return { x: (a.x + b.x) / 2, y: (a.y + a.h / 2 + b.y - b.h / 2) / 2 };
  };

  const onDown = (e: PointerEvent) => {
    if (!primary(e) || phase !== 'run') return;
    const { k, cx, cy } = layout();
    const p = stage.pt(e);
    const u = { x: (p.x - cx) / k, y: (p.y - cy) / k };
    let best = -1;
    let bd = 8;
    pz.pipes.forEach((pp, i) => {
      const vp = valvePos(pp);
      const d = Math.hypot(u.x - vp.x, u.y - vp.y);
      if (d < bd) {
        bd = d;
        best = i;
      }
    });
    if (best >= 0) toggle(best, e.timeStamp);
  };
  stage.canvas.addEventListener('pointerdown', onDown);
  const offs = [
    listen('keydown', (e) => {
      if (!gameKey(e) || e.repeat || e.defaultPrevented) return;
      if (e.code === 'Space') {
        e.preventDefault();
        togglePause(e.timeStamp);
        return;
      }
      const i = KEYS.indexOf(e.key.toLowerCase());
      if (i >= 0) {
        e.preventDefault();
        toggle(i, e.timeStamp);
      }
    }),
  ];
  const onVis = () => {
    if (document.hidden && pausedAt == null && phase === 'run') togglePause(performance.now());
  };
  document.addEventListener('visibilitychange', onVis);

  stage.draw = (now) => {
    const c = stage.ctx;
    const { k, cx, cy, ctrlY } = layout();
    const X = (u: number) => cx + u * k;
    const Y = (u: number) => cy + u * k;
    advance(now);
    if (lastMsg && phase === 'run') {
      api.prompt(lastMsg, 'Close the valve feeding it');
      lastMsg = ' ';
    }
    // Pipes, with valves and a flow cue only where liquid is really moving.
    pz.pipes.forEach((p, i) => {
      const a = pz.nodes[p.from];
      const b = pz.nodes[p.to];
      const x1 = X(a.x + (b.x - a.x) * 0.15);
      const y1 = Y(a.y + a.h / 2);
      const x2 = X(b.x - (b.x - a.x) * 0.15);
      const y2 = Y(b.y - b.h / 2);
      const flowing = open[i] && phase === 'run' && (V[p.from] > 1e-6 || sandbox());
      c.save();
      c.lineCap = 'round';
      line(c, x1, y1, x2, y2, pal.ink2, 7);
      line(c, x1, y1, x2, y2, pal.paper2, 3.5);
      if (open[i]) line(c, x1, y1, x2, y2, pal.liquid, 3.5);
      c.restore();
      if (flowing) {
        c.save();
        c.setLineDash([4, 6]);
        c.lineDashOffset = api.motion() && pausedAt == null ? -(now / 40) % 10 : 0;
        line(c, x1, y1, x2, y2, pal.liquidDeep, 2.5, [4, 6]);
        c.restore();
      }
      const vp = valvePos(p);
      const vx = X(vp.x);
      const vy = Y(vp.y);
      softShadow(c, vx, vy + 10, 12, 3.2, 1.2);
      if (open[i]) {
        c.beginPath();
        c.arc(vx, vy, 13.5, 0, Math.PI * 2);
        c.strokeStyle = pal.liquidDeep;
        c.lineWidth = 2;
        c.stroke();
      }
      c.fillStyle = pal.paper;
      c.beginPath();
      c.arc(vx, vy, 10, 0, Math.PI * 2);
      c.fill();
      c.strokeStyle = pal.ink;
      c.lineWidth = 2;
      c.stroke();
      const ang = Math.atan2(y2 - y1, x2 - x1) + (open[i] ? 0 : Math.PI / 2);
      line(c, vx - Math.cos(ang) * 7, vy - Math.sin(ang) * 7, vx + Math.cos(ang) * 7, vy + Math.sin(ang) * 7, pal.ink, 3);
      text(c, `${KEYS[i].toUpperCase()} · ${p.rate}/s`, vx + 14, vy, font.mono(9, 500), open[i] ? pal.ink : pal.ink3, 'left', 'middle');
    });
    // Containers
    pz.nodes.forEach((n, i) => {
      const x0 = X(n.x - n.w / 2);
      const x1 = X(n.x + n.w / 2);
      const yb = Y(n.y + n.h / 2);
      const yt = Y(n.y - n.h / 2);
      const lv = (clamp(V[i], 0, n.cap) / n.cap) * (yb - yt);
      softShadow(c, (x0 + x1) / 2, yb + 6, (x1 - x0) / 2 + 6, 5, 1.1);
      if (lv > 0.2) {
        liquidBody(
          c,
          (cc) => {
            cc.moveTo(x0, yb);
            cc.lineTo(x0, yb - lv);
            cc.lineTo(x1, yb - lv);
            cc.lineTo(x1, yb);
          },
          yb - lv,
          yb,
        );
        liquidSurface(c, x0, x1, yb - lv);
      }
      glassWall(c, [{ x: x0, y: yt }, { x: x0, y: yb }], 1);
      glassWall(c, [{ x: x1, y: yt }, { x: x1, y: yb }], -1);
      line(c, x0, yb, x1, yb, pal.ink, 2.5);
      if (n.goal != null) {
        const gy = yb - (n.goal / n.cap) * (yb - yt);
        line(c, x0 - 4, gy, x1 + 4, gy, pal.ink, 1.5, [4, 3]);
        const err = V[i] - n.goal;
        const onGoal = Math.abs(err) < 0.5;
        text(c, `${onGoal ? '✓ ' : ''}${n.name} ${V[i].toFixed(0)}/${n.goal}`, (x0 + x1) / 2, yb + 14, font.mono(10, onGoal ? 600 : 500), onGoal ? pal.ink : pal.ink2, 'center');
        if (phase === 'done' && Math.abs(err) > 0.05) tag(c, `${err > 0 ? '+' : '−'}${Math.abs(err).toFixed(1)}`, x1 + 18, gy, pal.signal, 10);
      } else text(c, `${n.name} ${V[i].toFixed(0)}`, (x0 + x1) / 2, yt - 8, font.mono(10, 500), pal.ink3, 'center');
    });
    if (spilled > 0.05) text(c, `spilled ${spilled.toFixed(1)} u²`, X(-49), Y(-48), font.mono(10, 500), pal.signal, 'left');
    if (pausedAt != null) text(c, '❚❚ PAUSED', X(49), Y(-48), font.mono(10, 500), pal.ink, 'right');
    if (phase === 'run') controls.draw(c, cx - 90, ctrlY - 6, 180);
    return phase === 'run';
  };

  return {
    reset,
    destroy: () => {
      clearTimeout(finTimer);
      controls.destroy();
      offs.forEach((f) => f());
      document.removeEventListener('visibilitychange', onVis);
      stage.canvas.removeEventListener('pointerdown', onDown);
    },
  };
};

export default factory;
